const { readdirSync, readFileSync, existsSync } = require('node:fs');
const { join, dirname, resolve } = require('node:path');

const IMPORT_RE = /(?:from\s+|require\s*\(\s*)[''"]([^''"]+)[''"]/g;

function collectFiles(dir, exts) {
  const files = [];
  function scan(d) {
    readdirSync(d, { withFileTypes: true }).forEach(e => {
      const p = join(d, e.name);
      if (e.isDirectory() && !e.name.startsWith('.') && e.name !== 'node_modules') scan(p);
      else if (e.isFile() && exts.some(ext => e.name.endsWith(ext))) files.push(p);
    });
  }
  scan(dir);
  return files;
}

function stripQuery(s) { return s.split('?')[0]; }
function isPackage(s) { return !s.startsWith('.') && !s.startsWith('/'); }
function exists(p) {
  return ['', '.js', '.ts', '.jsx', '.tsx', '.vue', '/index.js', '/index.ts'].some(e => existsSync(p + e));
}

const root = resolve(input.rootDir || '.');
const broken = [];
const files = collectFiles(root, ['.ts', '.tsx', '.vue']);

for (const file of files) {
  const lines = readFileSync(file, 'utf-8').split('\n');
  for (let i = 0; i < lines.length; i++) {
    IMPORT_RE.lastIndex = 0;
    let m;
    while ((m = IMPORT_RE.exec(lines[i])) !== null) {
      const spec = stripQuery(m[1] || '');
      if (isPackage(spec)) continue;
      if (spec.startsWith('.') && !exists(resolve(dirname(file), spec))) {
        broken.push({ file, line: i + 1, specifier: spec });
      }
    }
  }
}

return { broken_imports: broken };
